                  <img className="w-30 h-45 inline max-w-full max-h-50 mt-[0.3125rem] rounded-xs overflow-clip shadow-[var(--clr-2)_1px_2px_2px_0px]" data-ditto-id="style-figcaption" data-component="image" alt="a short stay in hell book cover" src="/assets/cloned/images/98cbd9b42296.png" />
